import { expect, test, uniqueName } from "../../fixtures";

const EXTRACTION_TIMEOUT = 120_000;

test.describe("review vendors", () => {
  test(
    "rejecting an extraction requires a note and returns the vendor to the member",
    { tag: "@REV-06" },
    async ({ apiAs }) => {
      // Arrange: a member creates a vendor and uploads all three documents.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");

      const createResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("REV06 Vendor"),
          category: "services",
          contact_email: `rev06-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@vendor.test`,
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendor = await createResponse.json();

      const kinds = ["w9", "insurance_certificate", "contract"] as const;
      const documentIds: Record<string, string> = {};
      for (const kind of kinds) {
        const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind,
            file: {
              name: `${kind}-${vendor.id}.pdf`,
              mimeType: "application/pdf",
              buffer: Buffer.from(`%PDF-1.4 fixture for ${kind} ${vendor.id}`),
            },
          },
        });
        expect(uploadResponse.status()).toBe(201);
        documentIds[kind] = (await uploadResponse.json()).id;
      }

      // Wait for every document to be extracted, then submit the vendor for review.
      for (const documentId of Object.values(documentIds)) {
        await expect
          .poll(
            async () => {
              const res = await member.get(`/api/documents/${documentId}`);
              return ((await res.json()) as { status: string }).status;
            },
            { timeout: EXTRACTION_TIMEOUT },
          )
          .toBe("extracted");
      }

      const submitResponse = await member.post(`/api/vendors/${vendor.id}/submit`);
      expect(submitResponse.status()).toBe(200);

      // Locate the W-9 extraction that the reviewer will act on.
      const extractionResponse = await reviewer.get(
        `/api/documents/${documentIds["w9"]}/extraction`,
      );
      expect(extractionResponse.status()).toBe(200);
      const extraction = await extractionResponse.json();
      expect(extraction.status).toBe("pending_review");

      // Act: reject without a note.
      const noNoteResponse = await reviewer.post(
        `/api/extractions/${extraction.id}/decision`,
        { data: { decision: "reject" } },
      );

      // Assert: validation error.
      expect(noNoteResponse.status()).toBe(422);

      // Act: reject with a note.
      const rejectResponse = await reviewer.post(
        `/api/extractions/${extraction.id}/decision`,
        { data: { decision: "reject", note: "Tax ID does not match" } },
      );
      expect(rejectResponse.status()).toBe(200);
      const rejected = await rejectResponse.json();
      expect(rejected.status).toBe("rejected");
      expect(rejected.review_note).toBe("Tax ID does not match");

      // Assert: vendor returned with status rejected.
      const vendorResponse = await member.get(`/api/vendors/${vendor.id}`);
      expect(vendorResponse.status()).toBe(200);
      expect((await vendorResponse.json()).status).toBe("rejected");

      // Assert: audit event recorded.
      const auditResponse = await member.get(`/api/vendors/${vendor.id}/audit`);
      expect(auditResponse.status()).toBe(200);
      const audit = (await auditResponse.json()) as {
        items: { action: string }[];
      };
      expect(audit.items.map((event) => event.action)).toContain("extraction.rejected");
    },
  );
});
